def check_file_path_valid(save_path):
    if len(save_path) > 256:
        msg = '传入路径非法，无法导出交易数据'
        return (False, msg)
    else:
        system = get_system()
        file_path_pattern = FILE_PATH_PATTERN_DICT.get(system)
        if file_path_pattern is None:
            return (False, '未知系统标识:%s' % system)
        elif re.match(file_path_pattern, save_path):
            return (True, '')
        return (False, '传入的路径中包含非法字符，无法导出交易数据')
