class TradingStore(BaseStore):
    trade_dict = None
    trading_id = 5001
    entrust_id = 700001
    COLUMNS = ['order_id', 'trading_id', 'entrust_id', 'security_code', 'order_type', 'volume', 'price', 'total_money', 'trading_fee', 'trade_time']
    def __init__(self):
        if self.trade_dict is None:
            self.trade_dict = {}
            return None
    def clear(self):
        self.trading_id = 5001
        self.entrust_id = 700001
        self.trade_dict.clear()
    def on_order_trade(self, event):
        trade = event.trade
        asset_type = trade.asset.type
        if asset_type == 'FUTURE':
            trade_info = [str(self.trading_id), str(self.entrust_id), trade.symbol, EntrustDirectionC[trade.entrust_direction], FUTURES_DIRECTION_ENUM[trade.futures_direction], float(trade.amount), decimal_round(trade.price, trade.asset.precision), decimal_round(trade.amount * trade.price, trade.asset.precision), trade.datetime.strftime('%Y-%m-%d %H:%M:%S')]
        elif asset_type == 'OPTION':
            trade_info = []
        else:
            trade_info = [str(self.trading_id), str(self.entrust_id), trade.symbol, EntrustDirectionC[trade.entrust_direction], float(trade.amount), decimal_round(trade.price, trade.asset.precision), decimal_round(trade.amount * trade.price, trade.asset.precision), trade.datetime.strftime('%Y-%m-%d %H:%M:%S')]
        self.trading_id += 1
        self.entrust_id += 1
        if trade.order_id in self.trade_dict:
            self.trade_dict[trade.order_id].append(trade_info)
            return None
        else:
            self.trade_dict[trade.order_id] = [trade_info]
    def get_trades(self):
        return self.trade_dict.copy()
    def get_trades_file(self, save_path='', identity=None):
        if save_path != '':
            result, message = check_file_path_valid(save_path)
            if not result:
                strategy_log.warning(message)
        result_list = [record for record in self._yield_business_record()]
        if not result_list:
            strategy_log.warning('未找到当日的交易记录')
        local_date = engine_instance().trading_dt.date()
        if save_path != '':
            new_path = os.path.join(notebook_path, save_path)
            if not os.path.exists(new_path):
                os.makedirs(new_path)
        else:
            new_path = notebook_path
        if identity is not None:
            account_book_file = '{0}.backtest.{1}.csv'.format(identity, local_date)
        else:
            account_book_file = 'backtest.{0}.csv'.format(local_date)
        file_full_path = os.path.join(new_path, account_book_file)
        ret = self.write_csv(file_full_path, result_list)
        if ret:
            return file_full_path
    def _yield_business_record(self):
        for order_id, trade_list in self.trade_dict.items():
            for trade_no, entrust_no, stock_code, trade_type, amount, price, balance, dt in trade_list:
                yield (order_id, trade_no, entrust_no, stock_code, trade_type, amount, price, balance, 0, dt)
    def write_csv(self, file_path, data):
        dir_path = os.path.dirname(file_path)
        try:
            os.makedirs(dir_path, exist_ok=True)
            df = pd.DataFrame(data, columns=self.COLUMNS)
            df.to_csv(file_path)
            return True
        except Exception as e:
            strategy_log.warning(_('保存成交流水失败，错误原因：{}'.format(e)))
            return False
            return False
    def save(self):
        return self.__dict__
    def load(self, trade_dict):
        self.__dict__ = trade_dict
class StoreCollection(object):
    def __init__(self):
        self.instance_dict = {}
    def get_instance(self, store_class):
        try:
            return self.instance_dict[store_class.__name__]
            return None
        except KeyError:
            r = store_class()
            store_class[None] = self.instance_dict
            return r
    def clear_instance(self):
        try:
            self.instance_dict.clear()
        except AttributeError:
            return None
    def save(self):
        return {k: v.save() for k, v in self.instance_dict.items() if hasattr(v, 'save')}
    def load(self, instance_dict):
        for k, v in instance_dict.items():
            self.get_instance(getattr(self, k)).load(v)
